package com.bank.salaryrank;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class NthHighestDemo {
    private static final Logger log = Logger.getLogger("SalaryRank");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", new BigDecimal("1000000")),
            new Employee("Priya", new BigDecimal("800000")),
            new Employee("Amit", new BigDecimal("800000")),
            new Employee("Neha", new BigDecimal("600000")));
        SalaryRankService service = new SalaryRankService();

        log.info(() -> "1st highest: " + service.nthHighest(staff, 1).orElse(null));
        log.info(() -> "2nd highest: " + service.nthHighest(staff, 2).orElse(null));
        log.info(() -> "3rd highest: " + service.nthHighest(staff, 3).orElse(null));
        log.info(() -> "5th (oob)  : " + service.nthHighest(staff, 5).orElse(null));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final BigDecimal salary;
        Employee(String name, BigDecimal salary) { this.name = name;
        this.salary = salary; }
    BigDecimal getSalary() { return salary; }
}

// ─── Would be in service/SalaryRankService.java ───
class SalaryRankService {
    Optional<BigDecimal> nthHighest(List<Employee> staff, int n) {
        if (n < 1) return Optional.empty();            // guard invalid N
        return staff.stream()
            .map(Employee::getSalary)
            .distinct()                                 // distinct salary ranks
            .sorted(Comparator.reverseOrder())           // descending
            .skip(n - 1L)                                // drop top n-1
            .findFirst();                                // → nth-highest
    }
}
